TIER = {"search_orders": 0, "draft_reply": 0,
        "send_reply": 1, "update_address": 1,
        "issue_refund": 2, "close_account": 2}

def act(state: dict) -> dict:
    call = state["proposed_call"]        # proposed by the LLM
    ____
    if tier >= 1:
        decision = interrupt({"call": call, "tier": tier,
                              "preview": render_effect(call)})
        if decision["action"] == "reject":
            return {"messages": [tool_result(call, "Rejected: " + decision["note"])]}
        if decision["action"] == "edit":
            call = {**call, "args": decision["args"]}
    audit.write(call=call, tier=tier)
    return {"messages": [tool_result(call, TOOLS[call["name"]](**call["args"]))]}
